     9	import net.officefloor.plugin.variable.Val;
    10	import net.officefloor.web.ObjectResponse;
    11	import org.springframework.http.ResponseEntity;
    12	import org.springframework.samples.petclinic.mapper.OwnerMapper;
    13	import org.springframework.samples.petclinic.model.Owner;
    14	import org.springframework.samples.petclinic.repository.OwnerRepository;
    15	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
    16	import org.springframework.samples.petclinic.util.MembershipLevels;
    17	import org.springframework.samples.petclinic.util.OwnerCreatedEvent;
    18	import org.springframework.samples.petclinic.util.OwnerIdentities;
    19	
    20	public class RespondWithOwnerCreated {
    21	
    22	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
    23	
    24	    /** Monotonically increasing sequence across all owner-created events in this JVM. */
    25	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
    26	
    27	    public void service(@Val Owner owner, OwnerRepository ownerRepository, OwnerMapper ownerMapper,
    28	            ObjectResponse<ResponseEntity<OwnerDto>> response) {
    29	        HouseholdMembers.stamp(owner, ownerRepository);
    30	        OwnerDto dto = ownerMapper.toOwnerDto(owner);
    31	        int membershipLevel = MembershipLevels.cappedLevelFor(owner);
    32	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
    33	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
    34	                membershipLevel, owner.getMembershipNumber());
    35	        // In addition to the audit line, emit the immutable structured event. Its customerCode field
    36	        // carries the owner's current primary identifier, so it follows a later switch to memberId.
    37	        OwnerCreatedEvent event = new OwnerCreatedEvent(EVENT_SEQ.incrementAndGet(), owner.getId(),
    38	                OwnerIdentities.primaryIdentifier(owner), membershipLevel);
    39	        AUDIT.info(event.toJson());
    40	        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    41	    }
    42	}

